import{_ as e,o as a,c as d,a3 as r}from"./chunks/framework.BlfGB29P.js";const S=JSON.parse('{"title":"轮询、SSE 与 WebSocket","description":"","frontmatter":{"title":"轮询、SSE 与 WebSocket","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/data/realtime.md","filePath":"frontend/decisions/data/realtime.md","lastUpdated":1785589115000}'),o={name:"frontend/decisions/data/realtime.md"};function i(l,t,h,n,c,s){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="轮询、sse-与-websocket" tabindex="-1">轮询、SSE 与 WebSocket <a class="header-anchor" href="#轮询、sse-与-websocket" aria-label="Permalink to &quot;轮询、SSE 与 WebSocket&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>实时通信选型首先看数据方向、更新频率、允许延迟和恢复语义。轮询、Server-Sent Events（SSE）与 WebSocket 都能传递“新消息”，但它们在连接生命周期、基础设施、鉴权和业务一致性上的责任不同。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>很多页面只需知道后台任务是否完成，不需要常驻双向连接；协同编辑则不能依赖数秒一次的轮询。即使传输实时，业务数据也可能重复、乱序或在重连窗口丢失，因此协议选择必须和事件 ID、快照及补偿策略一起决定。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-硬约束" tabindex="-1">2.1 硬约束 <a class="header-anchor" href="#_2-1-硬约束" aria-label="Permalink to &quot;2.1 硬约束&quot;">​</a></h3><ul><li>企业代理、网关、负载均衡和目标浏览器支持所选连接；</li><li>鉴权信息不能通过长期 URL 或日志泄漏，权限变化能使连接失效；</li><li>每用户连接数、服务器文件描述符和并发预算可承受；</li><li>断线、重连、重复、乱序和客户端休眠有明确处理；</li><li>写操作仍经过授权、幂等和业务校验，不能信任推送状态。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较数据方向、允许延迟、消息频率、连接规模、二进制需求、浏览器 API、网关支持、背压、重连、可观测性和运维复杂度。</p><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-定时或自适应轮询" tabindex="-1">3.1 定时或自适应轮询 <a class="header-anchor" href="#_3-1-定时或自适应轮询" aria-label="Permalink to &quot;3.1 定时或自适应轮询&quot;">​</a></h3><p>客户端周期性发起普通 HTTP 请求。适合低频、允许秒级或分钟级延迟的任务状态，基础设施和鉴权最简单。缺点是空请求、峰值同步和最坏延迟；可在页面隐藏时降频，并按任务阶段调整间隔。</p><h3 id="_3-2-sse" tabindex="-1">3.2 SSE <a class="header-anchor" href="#_3-2-sse" aria-label="Permalink to &quot;3.2 SSE&quot;">​</a></h3><p>服务端通过一个 HTTP 响应持续发送文本事件，天然适合服务端到浏览器的单向流。浏览器原生 <code>EventSource</code> 支持自动重连和事件 ID，但只能用 GET，不能任意设置请求头；Cookie 鉴权需配合 CSRF、同源和连接失效设计，Bearer Header 常需改用 <code>fetch</code> 流或受审查的封装。</p><h3 id="_3-3-websocket" tabindex="-1">3.3 WebSocket <a class="header-anchor" href="#_3-3-websocket" aria-label="Permalink to &quot;3.3 WebSocket&quot;">​</a></h3><p>建立全双工长连接，适合协同编辑、游戏、坐席和高频双向控制，可传输文本与二进制。团队需要处理握手后鉴权、心跳、背压、连接路由、协议版本和重连同步。</p><h3 id="_3-4-普通-http-加服务端通知" tabindex="-1">3.4 普通 HTTP 加服务端通知 <a class="header-anchor" href="#_3-4-普通-http-加服务端通知" aria-label="Permalink to &quot;3.4 普通 HTTP 加服务端通知&quot;">​</a></h3><p>写操作继续使用 HTTP，实时通道只提示“某资源已变化”，客户端再读取权威快照。这能降低推送事件作为事实来源的风险，适合多数业务应用。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>轮询</th><th>SSE</th><th>WebSocket</th></tr></thead><tbody><tr><td>方向</td><td>客户端请求/服务端响应</td><td>服务端到客户端</td><td>双向</td></tr><tr><td>典型延迟</td><td>由间隔决定</td><td>低</td><td>低</td></tr><tr><td>空闲成本</td><td>重复请求</td><td>保持连接</td><td>保持连接和心跳</td></tr><tr><td>浏览器接入</td><td>最简单</td><td>简单，但 Header 有限制</td><td>需自定义消息协议</td></tr><tr><td>自动重连</td><td>自行调度</td><td>原生 API 支持基础重连</td><td>自行实现</td></tr><tr><td>二进制</td><td>HTTP 可返回</td><td>不适合</td><td>支持</td></tr><tr><td>基础设施</td><td>最通用</td><td>需关闭代理缓冲</td><td>需升级和长连接支持</td></tr><tr><td>业务恢复</td><td>重新读状态</td><td>事件 ID + 快照</td><td>序列号 + 快照</td></tr></tbody></table><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>案例是仓储运营台：导出任务平均 40 秒完成；订单状态每用户每分钟约 20 次变化；用户只接收更新，所有操作仍通过 HTTP；公司网关支持 SSE，允许同源 Session Cookie。</p><p>推荐组合：导出任务采用退避轮询，因为生命周期短、允许 3 秒延迟；订单变化采用 SSE 推送 <code>{ resourceId, version }</code> 通知，客户端收到后按键刷新查询缓存；修改订单继续使用幂等 HTTP。</p><p>不采用 WebSocket，因为没有浏览器到服务器的高频消息，双向协议和连接集群不会产生相应收益。若未来增加多人拣货协同和低延迟位置同步，再单独评估 WebSocket。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>SSE 降低无效请求并改善订单可见延迟，同时增加长连接容量、代理配置和重连监控。事件只作为失效提示，避免遗漏一条事件就永久错误；客户端在重连后先拉取当前快照。</p><p>事件包含单调递增版本，客户端忽略旧版本。传输顺序只能描述单连接中的到达，不能替代跨服务的业务一致性。</p><p>退出成本较低：若 SSE 不稳定，可切回轮询；统一的资源版本和刷新接口继续有效。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>秒级延迟可接受的低频任务不需要 WebSocket。</li><li>原生 <code>EventSource</code> 不能直接设置任意 Authorization Header。</li><li>不要把连接成功当作用户仍有权限，权限变化需要服务端终止或重新验证。</li><li>不要假设重连后事件绝不丢失，应提供快照或可回放窗口。</li><li>移动设备后台会暂停连接，恢复流程必须可重复。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>运营台如何获得导出和订单状态更新</td></tr><tr><td>硬约束</td><td>同源 Session；代理支持；订单最多延迟 1 秒；断线后最终正确</td></tr><tr><td>候选</td><td>固定轮询、自适应轮询、SSE、WebSocket</td></tr><tr><td>决定</td><td>导出自适应轮询；订单 SSE 通知 + 快照刷新</td></tr><tr><td>证据</td><td>消息频率、代理试验、5 万连接压测、休眠恢复测试</td></tr><tr><td>接受代价</td><td>SSE 连接容量和重连监控；两种传输策略</td></tr><tr><td>退出路径</td><td>SSE 可退回版本化轮询，不改变业务写接口</td></tr><tr><td>验证指标</td><td>更新延迟、空请求数、在线连接、重连率、快照修正率、丢失投诉</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>浏览器需要高频双向消息、二进制传输、SSE 连接超过平台容量、企业代理异常率超过 1%，或轮询流量达到 API 容量的 10% 时复查。协议变化时先保留双轨灰度和快照恢复。</p>',35)])])}const _=e(o,[["render",i]]);export{S as __pageData,_ as default};
